head.script:
scwin.inc2_onpageload = function () {
    var log = $p.top().scwin.log;
    log("--- [include2] onpageload ---");
    log("  INC2_name = [" + scvar.INC2_name + "] (TWO 기대)");
    log("  INC1_name = [" + scvar.INC1_name + "] (ONE 기대 - 형제 include 변수 보존)");
    log("  TOP_name = [" + scvar.TOP_name + "] (TOP 기대 - 부모 변수 보존)");
    log("  키 목록 = " + Object.keys(scvar).join(", "));
};
